def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation that transforms s_in to s_out."""
    # Simple approach: find first difference and determine what needs to change
    if s_in == s_out:
        return None

    # Find first position where they differ
    min_len = min(len(s_in), len(s_out))
    pos = 0
    while pos < min_len and s_in[pos] == s_out[pos]:
        pos += 1

    # If we've reached the end of one string, it's an insertion/deletion
    if pos == len(s_in):
        # Insertion case
        return ("", s_out[pos:], pos)
    elif pos == len(s_out):
        # Deletion case  
        return (s_in[pos:], "", pos)
    else:
        # Substitution/insertion/deletion at pos
        # Check if we're inserting or replacing
        if len(s_in) < len(s_out):
            # Insertion - check if rest matches
            if s_in[pos:] == s_out[pos+1:]:
                return ("", s_out[pos], pos)
        elif len(s_in) > len(s_out):
            # Deletion - check if rest matches
            if s_in[pos+1:] == s_out[pos:]:
                return (s_in[pos], "", pos)
        else:
            # Same length - substitution
            return (s_in[pos], s_out[pos], pos)

# Analyze each changed pair
changed = [(0, 'yezf', 'xfgezf'), (2, 'czw', 'azw'), (3, 'eyjyv', 'exfgjxfgv')]

for idx, s_in, s_out in changed:
    edit = find_minimal_edit(s_in, s_out)
    print(f"{s_in} → {s_out}: {edit}")

