def propose_rule_candidates(s_in, s_out):
    """Generate candidate replacement rules from a transformation."""
    candidates = []

    # Try various substring replacements
    # Check for simple substitutions first
    for i in range(len(s_in)):
        for j in range(i+1, len(s_in)+1):
            pattern = s_in[i:j]
            if len(pattern) <= 3:
                # Check if replacing this pattern gives us the output
                temp = s_in.replace(pattern, s_out[i:i+len(pattern)])
                if temp == s_out:
                    candidates.append((pattern, s_out[i:i+len(pattern)]))

    # Also check for insertions/deletions
    # For now, let's focus on direct substitutions

    # Simple substitutions
    for i in range(min(len(s_in), len(s_out))):
        if s_in[i] != s_out[i]:
            # Single character replacement
            if len(s_in) == len(s_out):
                candidates.append((s_in[i], s_out[i]))
            break

    # If lengths are different, consider insertion/deletion
    if len(s_in) < len(s_out):
        # Look for insertion
        for i in range(len(s_in) + 1):
            if i < len(s_out) and s_in[:i] == s_out[:i] and s_in[i:] == s_out[i+1:]:
                candidates.append(("", s_out[i], i))
                break
    elif len(s_in) > len(s_out):
        # Look for deletion
        for i in range(len(s_out) + 1):
            if i < len(s_in) and s_in[:i] == s_out[:i] and s_in[i+1:] == s_out[i:]:
                candidates.append((s_in[i], "", i))
                break

    # Add general cases
    if len(s_in) <= 3 and len(s_out) <= 3:
        candidates.append((s_in, s_out))

    return candidates

